  \left\{\begin{aligned}
  \mathcal{K}_1\left(\int_\Omega \left(|\nabla u|^2+|v|^2\right)dx\right)\Delta u+\left|\Omega\right|^{-1}\mathcal{K}_2\left(\int_\Omega \left(|\nabla u|^2+|v|^2\right)dx\right)u\log\left(1+\frac{|u|^2}{\alpha^2}\right)-h_1(x)u&=\mathcal{G}(u,v)\\
